USE order_product;
CREATE TABLE IF NOT EXISTS product_spu(id BIGINT PRIMARY KEY,name VARCHAR(128) NOT NULL,status TINYINT NOT NULL,create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS product_sku(id BIGINT PRIMARY KEY,spu_id BIGINT NOT NULL,sku_name VARCHAR(128) NOT NULL,price_cent BIGINT NOT NULL,status TINYINT NOT NULL,create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),KEY idx_spu_id(spu_id)) ENGINE=InnoDB;
